// Process Slack file response and filter audio files
const files = $input.first().json.files;

if (!files || files.length === 0) {
  return [{ json: { audioFiles: [] } }];
}

const audioFiles = files.filter(file => {
  const mimeType = file.mimetype || '';
  return mimeType.includes('audio') || 
         mimeType.includes('octet-stream') ||
         file.name?.toLowerCase().endsWith('.wav') ||
         file.name?.toLowerCase().endsWith('.mp3') ||
         file.name?.toLowerCase().endsWith('.m4a') ||
         file.name?.toLowerCase().endsWith('.ogg');
});

if (audioFiles.length > 0) {
  const file = audioFiles[0];
  return [{
    json: {
      fileId: file.id,
      filename: file.name,
      urlPrivate: file.url_private,
      mimeType: file.mimetype,
      timestamp: file.created,
      user: file.user
    }
  }];
}

return [{ json: { audioFiles: [] } }];

// Convert ElevenLabs word-level output to conversational transcript
const words = $json.words;

if (!words || words.length === 0) {
  return [{
    json: {
      formattedTranscript: "",
      error: "No transcription data received"
    }
  }];
}

const sortedWords = words.sort((a, b) => a.start - b.start);
let transcript = "";
let currentSpeaker = null;

for (const word of sortedWords) {
  const speakerId = word.speaker_id || 'unknown';

  if (currentSpeaker !== speakerId) {
    if (transcript !== "") transcript += "\n";
    const formattedSpeaker = `Speaker ${speakerId.split('_')[1] || speakerId}`;
    transcript += `${formattedSpeaker}: ${word.text}`;
    currentSpeaker = speakerId;
  } else {
    transcript += ` ${word.text}`;
  }
}

return [{
  json: {
    formattedTranscript: transcript,
    wordCount: sortedWords.length,
    speakers: [...new Set(words.map(w => w.speaker_id))].length
  }
}];

