// Format analysis results for Slack
const item = $input.first().json;
const output = item.output || item;

const sentimentEmoji = {
  'Positive': '😊',
  'Negative': '😞',
  'Neutral': '😐'
};

const actionItems = output.action_items || [];
const actionItemsFormatted = actionItems.length > 0 
  ? actionItems.map(item => `• ${item}`).join('\n')
  : '• No action items identified';

return [{
  json: {
    ...output,
    sentiment_emoji: sentimentEmoji[output.client_sentiment] || '',
    action_items_formatted: actionItemsFormatted,
    filename: item.filename || 'Unknown',
    duration: item.duration || 'N/A'
  }
}];

// Send error message to Slack via webhook
const error = $json.error || 'Unknown error occurred';

return [{
  json: {
    text: `❌ *Call Analysis Failed*

An error occurred while analyzing the call recording:

\`\`\`${error}\`\`\`

Please try again or contact support.`
  }
}];
